// Backward compat
export const CONNECTION_TIMES = CONNECTION_TIMES_7H;

/** Parse total hours and number of days from duree string like "24 heures (4 jours)" */
export function parseDuree(duree: string): { totalHours: number; days: number; hoursPerDay: number } {
  const hMatch = duree.match(/(\d+)\s*heures?/i);
  const dMatch = duree.match(/(\d+)\s*jours?/i);
  const totalHours = hMatch ? parseInt(hMatch[1]) : 21;
  const days = dMatch ? parseInt(dMatch[1]) : 3;
  const hoursPerDay = days > 0 ? totalHours / days : 7;
  return { totalHours, days, hoursPerDay };
}

/** Get appropriate connection times based on hours per day */
export function getConnectionTimes(f: FormationInfo): typeof CONNECTION_TIMES_7H {
  const { hoursPerDay } = parseDuree(f.duree);
  return hoursPerDay <= 6 ? CONNECTION_TIMES_6H : CONNECTION_TIMES_7H;
}

/** Detect if formation includes Saturdays (e.g. massage postpartum/prénatal 6-day intensive) */
export function formationIncludesSaturday(f: FormationInfo): boolean {
  const t = (f.intitule || "").toLowerCase();
  return t.includes("massage") || t.includes("postpartum") || t.includes("post-partum") || t.includes("prénatal") || t.includes("prenatal");
}

export function getFormationDays(f: FormationInfo): string[] {
  if (!f.dateDebut || !f.dateFin) return ["Jour 1", "Jour 2", "Jour 3"];
  const lire = (v: string): Date => {
    const m = v.trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
    if (m) return new Date(+m[3], +m[2] - 1, +m[1]);
    const iso = v.trim().match(/^(\d{4})-(\d{2})-(\d{2})/);
    return iso ? new Date(+iso[1], +iso[2] - 1, +iso[3]) : new Date(v);
  };
  const start = lire(f.dateDebut);
  const end = lire(f.dateFin);
  const days: string[] = [];
  const current = new Date(start);
  const includeSat = formationIncludesSaturday(f);
  while (current <= end) {
    if (estJourFormation(current, start, end, { includeSat })) {
      days.push(current.toLocaleDateString("fr-FR", { weekday: "long", year: "numeric", month: "long", day: "numeric" }));
    }
    current.setDate(current.getDate() + 1);
  }
  return days.length > 0 ? days : ["Jour 1", "Jour 2", "Jour 3"];
}

/**
 * Complète l'organisme saisi SANS jamais injecter les données d'un autre organisme
 * (l'ancien repli sur « FormaPro Excellence » faisait sortir son NDA, ses référents…
 * dans les dossiers). Un champ vide reste vide, sauf les rôles internes qui reviennent
 * au dirigeant (convention des dossiers : un OF unipersonnel cumule les fonctions).
 */
export function mergeOrganisme(userOrg: OrganismeInfo): OrganismeInfo {
  const u: Partial<OrganismeInfo> = userOrg || {};
  const txt = (x: unknown) => (typeof x === "string" ? x.trim() : "");
  const rempli = (x: unknown) => (typeof x === "string" ? x.trim() !== "" : Array.isArray(x) ? x.length > 0 : x != null && x !== false);
  // Aucune saisie : aperçu de démonstration de l'application.
  if (!Object.values(u).some(rempli)) return { ...SAMPLE_ORGANISME };
  const merged: OrganismeInfo = {
    nom: "", siret: "", adresse: "", codePostal: "", ville: "", telephone: "", email: "", siteWeb: "", nda: "",
    dirigeant: "", responsablePedagogique: "", referentHandicap: "", referentQualite: "", poleAdministratif: "",
    relationEntreprises: "", referentMobilite: "", domainesFormation: "", typesActions: ["actions-formation"],
    certifications: "", outilsUtilises: "", version: "1", dateMaj: new Date().toISOString().slice(0, 10),
  };
  for (const key of Object.keys(u) as (keyof OrganismeInfo)[]) {
    if (rempli(u[key])) (merged as any)[key] = u[key];
  }
  const dirigeant = txt(u.dirigeant);
  const roles: (keyof OrganismeInfo)[] = ["responsablePedagogique", "referentHandicap", "referentQualite", "poleAdministratif", "relationEntreprises", "referentMobilite"];
  for (const r of roles) if (!txt(merged[r])) (merged as any)[r] = dirigeant;
  if (!txt(merged.outilsUtilises)) merged.outilsUtilises = "Google Meet, Zoom, messagerie électronique";
  // Dirigeant : le tampon seul s'il existe, sinon la signature — jamais les deux ensemble.
  if (txt(merged.tamponUrl)) merged.signatureUrl = "";
  return merged;
}

